// ---------------------------------------------------------------------------
// CrazySupportHub - clasificacion por reglas.
// Calibrado contra los tickets ya enriquecidos de tickets-seed.json.
// ---------------------------------------------------------------------------

// El webhook entrega el cuerpo en `body`; si se invoca el nodo suelto, en la raiz.
const input = $input.first().json;
const ticket = input.body ?? input;

const ticketId = Number(ticket.ticketId);
if (!Number.isInteger(ticketId) || ticketId <= 0) {
  throw new Error('Payload invalido: falta un ticketId numerico.');
}

// Se normaliza a minusculas y sin tildes para que las reglas no dependan
// de como el usuario escribio el acento.
const normalize = (value) =>
  String(value ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

const text = `${normalize(ticket.title)} ${normalize(ticket.description)}`;
const has = (...needles) => needles.some((n) => text.includes(n));

// --- Categoria -------------------------------------------------------------
// El orden importa: "consulta sobre planes y precios" contiene la palabra
// "precios" pero es una pregunta comercial, no un problema de facturacion.
// Por eso las senales de "other" se evaluan primero.
let category;
if (has('sugerencia', 'feedback', 'me encantaria', 'estoy evaluando', 'consulta sobre', 'comparativa')) {
  category = 'other';
} else if (
  has('factura', 'facturacion', 'cobro', 'cargo', 'reembolso', 'suscripcion',
      'ciclo de cobro', 'dar de baja', 'plan pro', 'tarjeta', 'datos fiscales')
) {
  category = 'billing';
} else if (
  has('error', 'falla', 'fallo', 'crash', 'se cierra', 'se cae', 'no carga', 'no funciona',
      'no recibo', 'notificacion', 'exportar', 'dashboard', 'pantalla', 'lento', 'bug', '500')
) {
  category = 'technical';
} else if (
  has('cuenta', 'email', 'correo', 'contrasena', 'usuario', 'perfil', 'acceso', 'restablecer')
) {
  category = 'account';
} else {
  category = 'other';
}

// --- Prioridad -------------------------------------------------------------
// "se cierra sola" aparece tanto en un crash puntual como en la expulsion
// constante de sesion, asi que no sirve para distinguir urgencia. Lo que
// separa urgente de medio es la recurrencia y el bloqueo total.
let priority;
if (has('urgente', 'constantemente', 'cada pocos minutos', 'todo el tiempo', 'no puedo trabajar',
        'todos los usuarios', 'caido', 'inaccesible', 'perdida de datos')) {
  priority = 'urgent';
} else if (has('duplicad', 'error 500', 'error del servidor', 'no puedo acceder', 'fraude', 'cobro indebido')) {
  priority = 'high';
} else if (has('sugerencia', 'consulta', 'duda', 'me encantaria', 'como procedo', 'quisiera saber',
               'me gustaria', 'solicito', 'estoy evaluando')) {
  priority = 'low';
} else {
  priority = 'medium';
}

// --- Tags ------------------------------------------------------------------
// Etiquetas derivadas de lo que realmente aparecio en el texto, al estilo de
// las del seed. Se limitan a 4 para que sigan siendo utiles como filtro.
const TAG_RULES = [
  ['factura', 'facturacion'],  ['cobro', 'facturacion'],   ['cargo', 'facturacion'],
  ['reembolso', 'reembolso'],  ['duplicad', 'duplicado'],  ['suscripcion', 'suscripcion'],
  ['dar de baja', 'cancelacion'], ['datos fiscales', 'datos-fiscales'],
  ['android', 'android'],      ['iphone', 'ios'],          ['crash', 'crash'],
  ['se cierra', 'crash'],      ['error 500', 'server-error'], ['exportar', 'export'],
  ['pdf', 'pdf'],              ['dashboard', 'dashboard'], ['no carga', 'no-carga'],
  ['sesion', 'sesion'],        ['contrasena', 'password'], ['email', 'email'],
  ['correo', 'email'],         ['cuenta', 'cuenta'],       ['notificacion', 'notificaciones'],
  ['sugerencia', 'feedback'],  ['planes', 'planes'],       ['precios', 'planes'],
];

const tags = [];
for (const [needle, tag] of TAG_RULES) {
  if (text.includes(needle) && !tags.includes(tag)) tags.push(tag);
  if (tags.length === 4) break;
}
if (tags.length === 0) tags.push(category);

return [{ json: { ticketId, priority, category, tags } }];
